-- YG-1676 yıllık iç denetim planı; YG-1680 bulgu takibi; YG-807 Resmî Gazete taraması; YG-586 sosyal medya izleme kaydı.
CREATE TABLE ic_denetim_plani (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), yil integer NOT NULL UNIQUE, surecler text[] NOT NULL CHECK (cardinality(surecler) > 0), aciklama text, durum text NOT NULL DEFAULT 'CEO Onayında' CHECK (durum IN ('CEO Onayında', 'Yürürlükte', 'İade Edildi', 'Reddedildi')), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), onay_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
ALTER TABLE ic_denetim_bulgu ADD COLUMN durum text NOT NULL DEFAULT 'Açık' CHECK (durum IN ('Açık', 'Kapandı')), ADD COLUMN takip_sonucu text CHECK (takip_sonucu IN ('Etkin', 'Etkin Değil')), ADD COLUMN takip_notu text, ADD COLUMN takip_eden_ref text REFERENCES kullanici_hesabi (kimlik), ADD COLUMN takip_zamani timestamptz;
CREATE TABLE ic_denetim_bulgu_takip (kimlik bigserial PRIMARY KEY, bulgu_ref uuid NOT NULL REFERENCES ic_denetim_bulgu (kimlik), sonuc text NOT NULL CHECK (sonuc IN ('Etkin', 'Etkin Değil')), notu text NOT NULL, yapan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE resmi_gazete_tarama (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), donem text NOT NULL UNIQUE, sonuc text CHECK (sonuc IN ('Değişiklik Yok', 'Değişiklik Var')), aciklama text, mum_listesi text[] NOT NULL DEFAULT '{}', tarayan_ref text REFERENCES kullanici_hesabi (kimlik), tarama_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
CREATE TABLE sosyal_medya_kaydi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), kayit_no text NOT NULL UNIQUE, kaynak text NOT NULL CHECK (kaynak IN ('Personel Bildirimi', 'Haftalık Tarama')), platform text NOT NULL, baglanti text, ozet text NOT NULL, tespit_zamani timestamptz NOT NULL, olumsuz boolean NOT NULL, degerlendirme text, sonuc text CHECK (sonuc IN ('İşlem Gerekmez', 'Sözcüye İletildi', 'Hukuka İletildi', 'Kapatıldı')), giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), degerlendiren_ref text REFERENCES kullanici_hesabi (kimlik), degerlendirme_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON ic_denetim_plani, resmi_gazete_tarama, sosyal_medya_kaydi TO yatonet_uygulama; GRANT UPDATE ON ic_denetim_bulgu TO yatonet_uygulama; GRANT SELECT, INSERT ON ic_denetim_bulgu_takip TO yatonet_uygulama; GRANT USAGE ON SEQUENCE ic_denetim_bulgu_takip_kimlik_seq TO yatonet_uygulama;
